// Original approved Home artwork. Only SVG viewports are changed, not the image pixels.
const original='data:image/png;base64,';
const crops={bike:[52,767,167,96],auto:[272,767,164,96],freight:[693,767,177,96]};
export function goodsArtworkKind(vehicle:any):'bike'|'auto'|null {
 const info=vehicle?.vehicle_info||vehicle?.vehicle||vehicle;
 const label=[typeof vehicle==='string'?vehicle:'',vehicle?.slug,vehicle?.name,vehicle?.vehicle_type?.name,vehicle?.vehicle_type?.slug,info?.name,info?.vehicle_type?.name,info?.vehicle_type?.slug,info?.vehicle_type_name].filter(v=>typeof v==='string').join(' ').toLowerCase();
 if(/bike|motorcycle|two.?wheeler/.test(label))return 'bike';if(/auto|rickshaw|three.?wheeler/.test(label))return 'auto';return null;
}
const svgCache:Record<string,string>={};
export function vehicleSvg(kind:'bike'|'auto',freight=false){const key=kind==='auto'&&freight?'freight':kind;if(svgCache[key])return svgCache[key];const [x,y,w,h]=crops[key];return svgCache[key]='<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'"><image x="'+(-x)+'" y="'+(-y)+'" width="916" height="1717" xlink:href="'+original+'"/></svg>';}
const cache:Record<string,string>={};
export function vehicleMarker(vehicle:any,fallback?:string,freight=false):string|undefined {const kind=goodsArtworkKind(vehicle)||goodsArtworkKind(fallback);if(!kind)return fallback;const key=kind+(freight?'freight':'');return cache[key]||(cache[key]='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(vehicleSvg(kind,freight)));}
